import{_ as a,a as n,c as t,ac as r}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"搜索与回溯","description":"先区分子集、组合与排列，再把合法性约束和可证明的剪枝放进搜索过程；迷宫示例返回可行路径，数独返回第一组解。","frontmatter":{"title":"搜索与回溯","description":"先区分子集、组合与排列，再把合法性约束和可证明的剪枝放进搜索过程；迷宫示例返回可行路径，数独返回第一组解。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"algorithms","title":"算法","link":"/topics/algorithms/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"问题与数据结构","scope":"general","audience":"general","group":"原理与设计","summary":"先区分子集、组合与排列，再把合法性约束和可证明的剪枝放进搜索过程；迷宫示例返回可行路径，数独返回第一组解。","status":"active","related":[{"title":"Go 算法与容器实践：遍历、排序、递推与堆","link":"/principles/algorithms/exercises/go-interview-algorithm","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组","link":"/principles/algorithms/exercises/leetcode-arrary","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 两数之和至移除元素","link":"/principles/algorithms/exercises/leetcode-arrary-part-01","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 搜索插入位置至完整入口与预期结果","link":"/principles/algorithms/exercises/leetcode-arrary-part-02","kind":"算法推演","scope":"general","audience":"general"},{"title":"0/1 背包","link":"/principles/algorithms/dp/knapsack-01","kind":"问题与数据结构","scope":"general","audience":"general"}],"prev":{"text":"数独求解","link":"/principles/algorithms/backtracking/sudoku"},"next":{"text":"子集枚举","link":"/principles/algorithms/backtracking/subsets"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"数独求解","link":"/principles/algorithms/backtracking/sudoku"},"next":{"text":"子集枚举","link":"/principles/algorithms/backtracking/subsets"}},"headers":[],"relativePath":"principles/algorithms/backtracking/algorithms-backtracking-general-general.md","filePath":"principles/algorithms/backtracking/algorithms-backtracking-general-general.md"}'),i={name:"principles/algorithms/backtracking/algorithms-backtracking-general-general.md"};function s(p,e,c,d,o,l){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="搜索与回溯" tabindex="-1">搜索与回溯 <a class="header-anchor" href="#搜索与回溯" aria-label="Permalink to &quot;搜索与回溯&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>各段是独立 main.go，在新模块中只保存当前一个例子；本轮未执行，下面输出按搜索顺序静态推导。n、k 等数量需非负且输入规模足够小；组合选自 1..n，重复值排列不会自动去重。数独初盘需合法、只含点号或 1..9；无解会返回 false，迷宫无路返回空路径。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>枚举任意选择、固定数量选择或全部顺序</td><td><a href="#entry-subsets-50cdd2e90e">子集枚举</a>、<a href="#entry-combinations-b27e054c65">组合</a>、<a href="#entry-permutations-d91fd873d1">全排列</a></td><td>子集有 2ⁿ 个，排列有 n! 个；组合通过递增候选下标避免顺序重复。</td></tr><tr><td>尽早停止无法达到目标的分支</td><td><a href="#entry-branch-pruning-f61aa078ea">剪枝</a></td><td>子集和示例依赖非负元素；含负数时当前和超过目标仍可能被抵消。</td></tr><tr><td>生成合法括号或放置互不冲突的皇后</td><td><a href="#entry-generate-parentheses-9bfd3c2268">括号生成</a>或<a href="#entry-n-queens-40b622b5ea">N 皇后</a></td><td>在扩展时检查左右括号数量，或列与对角线占用；返回后撤销选择。</td></tr><tr><td>填满带行、列和宫格约束的棋盘</td><td><a href="#entry-sudoku-35e7cbd110">数独求解</a></td><td>示例找到第一组解即返回；初始棋盘合法性仍须检查。</td></tr><tr><td>在网格中寻找一条可行路径</td><td><a href="#entry-maze-search-4e2bb2aaca">迷宫 DFS</a></td><td>访问标记避免重复进入，回溯维护路径；若要最短步数，应使用 BFS。</td></tr></tbody></table><h2 id="scene-enumerate-choices" tabindex="-1">区分子集、组合与排列的搜索空间 <a class="header-anchor" href="#scene-enumerate-choices" aria-label="Permalink to &quot;区分子集、组合与排列的搜索空间 {#scene-enumerate-choices}&quot;">​</a></h2><h3 id="entry-subsets-50cdd2e90e" tabindex="-1">子集枚举 <a class="header-anchor" href="#entry-subsets-50cdd2e90e" aria-label="Permalink to &quot;子集枚举 {#entry-subsets-50cdd2e90e}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-subsets-50cdd2e90e-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/backtracking/subsets">子集枚举</a>。</p><p>位移宽度受整数位数限制；很大的 n 应使用递归或迭代扩展且避免一次保存所有结果。</p><h3 id="entry-combinations-b27e054c65" tabindex="-1">组合 <a class="header-anchor" href="#entry-combinations-b27e054c65" aria-label="Permalink to &quot;组合 {#entry-combinations-b27e054c65}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-combinations-b27e054c65-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/backtracking/combinations">组合</a>。</p><p>可加入“剩余候选不足”判断，减少不可能完成的分支。</p><h3 id="entry-permutations-d91fd873d1" tabindex="-1">全排列 <a class="header-anchor" href="#entry-permutations-d91fd873d1" aria-label="Permalink to &quot;全排列 {#entry-permutations-d91fd873d1}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-permutations-d91fd873d1-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/backtracking/permutations">全排列</a>。</p><p>输出本身有 n! 个，输入稍大就会迅速增长；重复元素还需去重规则。</p><h2 id="scene-prune-impossible" tabindex="-1">用可证明的边界跳过无解分支 <a class="header-anchor" href="#scene-prune-impossible" aria-label="Permalink to &quot;用可证明的边界跳过无解分支 {#scene-prune-impossible}&quot;">​</a></h2><h3 id="entry-branch-pruning-f61aa078ea" tabindex="-1">剪枝 <a class="header-anchor" href="#entry-branch-pruning-f61aa078ea" aria-label="Permalink to &quot;剪枝 {#entry-branch-pruning-f61aa078ea}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-branch-pruning-f61aa078ea-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/backtracking/branch-pruning">剪枝</a>。</p><p>这段回溯是在求子集和：每个元素只有选或不选两个分支。剪枝依赖元素非负；例如输入 {5,-2}、目标 3 时，选 5 后虽然超过目标，后面的 -2 仍能抵消，直接剪掉这条分支就会漏解。</p><p>有效剪枝必须建立在可证明的上下界上。</p><h2 id="scene-enforce-constraints" tabindex="-1">边构造边检查括号与棋盘约束 <a class="header-anchor" href="#scene-enforce-constraints" aria-label="Permalink to &quot;边构造边检查括号与棋盘约束 {#scene-enforce-constraints}&quot;">​</a></h2><h3 id="entry-generate-parentheses-9bfd3c2268" tabindex="-1">括号生成 <a class="header-anchor" href="#entry-generate-parentheses-9bfd3c2268" aria-label="Permalink to &quot;括号生成 {#entry-generate-parentheses-9bfd3c2268}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-generate-parentheses-9bfd3c2268-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/backtracking/generate-parentheses">括号生成</a>。</p><p>到长度 2n 时得到完整答案，不需要先生成非法串再过滤。</p><h3 id="entry-n-queens-40b622b5ea" tabindex="-1">N 皇后 <a class="header-anchor" href="#entry-n-queens-40b622b5ea" aria-label="Permalink to &quot;N 皇后 {#entry-n-queens-40b622b5ea}&quot;">​</a></h3><p><span id="输出-5"></span><span id="示例-5"></span></p><p><span id="entry-n-queens-40b622b5ea-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/backtracking/n-queens">N 皇后</a>。</p><p>搜索仍可能指数增长，但即时排除冲突位置比先枚举整张棋盘高效得多。</p><h3 id="entry-sudoku-35e7cbd110" tabindex="-1">数独求解 <a class="header-anchor" href="#entry-sudoku-35e7cbd110" aria-label="Permalink to &quot;数独求解 {#entry-sudoku-35e7cbd110}&quot;">​</a></h3><p><span id="输出-6"></span><span id="示例-6"></span></p><p><span id="entry-sudoku-35e7cbd110-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/backtracking/sudoku">数独求解</a>。</p><p>示例返回找到的第一组解；实际应用还应检查初始棋盘是否已违反规则。</p><h2 id="scene-find-grid-path" tabindex="-1">在迷宫中维护访问状态与路径 <a class="header-anchor" href="#scene-find-grid-path" aria-label="Permalink to &quot;在迷宫中维护访问状态与路径 {#scene-find-grid-path}&quot;">​</a></h2><h3 id="entry-maze-search-4e2bb2aaca" tabindex="-1">迷宫搜索 <a class="header-anchor" href="#entry-maze-search-4e2bb2aaca" aria-label="Permalink to &quot;迷宫搜索 {#entry-maze-search-4e2bb2aaca}&quot;">​</a></h3><p><span id="输出-7"></span><span id="示例-7"></span></p><p><span id="entry-maze-search-4e2bb2aaca-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/backtracking/maze-search">迷宫搜索</a>。</p><p>DFS 找到的是一条路径，不保证步数最短，最短路应使用 BFS。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>HasSubsetSum 对含负数数组还能用 sum&gt;target 剪枝吗？提示：用 {5,-2}、目标 3 追踪首条分支。</p><details class="details custom-block"><summary>参考解法</summary><p>不能；选 5 后当前和超过 3，但后续 -2 能抵消得到解。当前实现前提为非负输入，不能删掉该前提后仍声称剪枝正确。</p></details>',52)])])}const u=a(i,[["render",s]]);export{b as __pageData,u as default};
